        function edgeToObject(edge, index) { return { id: `e${index + 1}`, u: edge[0], v: edge[1], w: Number(edge[2]) }; }

        function getNodePositions(nodes) {
            const centerX = 350, centerY = 180, radius = 120;
            return nodes.map((id, idx) => {
                const angle = (Math.PI * 2 * idx) / nodes.length - Math.PI / 2;
                return { id, x: centerX + radius * Math.cos(angle), y: centerY + radius * Math.sin(angle) };
            });
        }

        function makeLabelState(nodes) {
            const label = {};
            nodes.forEach((node, index) => { label[node] = index + 1; });
            return {
                label,
                relabel(fromNode, toNode) {
                    const oldLabel = label[toNode];
                    const newLabel = label[fromNode];
                    if (oldLabel === newLabel) return { oldLabel, newLabel, changedNodes: [] };
                    const changedNodes = [];
                    Object.keys(label).forEach(node => {
                        if (label[node] === oldLabel) {
                            label[node] = newLabel;
                            changedNodes.push(node);
                        }
                    });
                    return { oldLabel, newLabel, changedNodes };
                },
                snapshot() { return { label: clone(label) }; }
            };
        }

        function getComponentsFromSnapshot(nodes, snapshot) {
            const groups = {};
            nodes.forEach(node => {
                const key = snapshot.label[node];
                if (!groups[key]) groups[key] = [];
                groups[key].push(node);
            });
            return Object.values(groups).map(group => group.sort());
        }

        function getAnswerByConcept(concept) {
            const found = qaKnowledgeBase.find(item => item.topic === concept);
            return found ? found.answer : conceptExplanations[concept] || '暂无预设解释。';
        }

        function showKnowledgeExplanation(concept, extraText = '') {
            currentKnowledgeConcept = concept;
            knowledgeTopic.textContent = conceptLabels[concept] || concept;
            const main = conceptExplanations[concept] || getAnswerByConcept(concept);
            knowledgeText.textContent = extraText ? `${main}\n\n当前步骤说明：${extraText}\n\n学习建议：${conceptAdvice[concept] || ''}` : `${main}\n\n学习建议：${conceptAdvice[concept] || ''}`;
        }

        function loadGraph(graphDef) {
            const nodes = [...graphDef.nodes];
            graphData = {
                name: graphDef.name,
                nodes: getNodePositions(nodes),
                edges: graphDef.edges.map(edgeToObject),
                sortedEdges: graphDef.edges.map(edgeToObject).sort((a, b) => a.w - b.w || a.u.localeCompare(b.u) || a.v.localeCompare(b.v))
            };
            buildAnimationSteps();
            resetViewState(true);
            renderCurrentStepPreview();
        }

        function buildAnimationSteps() {
            animationSteps = [];
            statsRows = [];
            const nodeIds = graphData.nodes.map(n => n.id);
            const labelState = makeLabelState(nodeIds);
            let mstEdges = [], rejectedEdges = [], totalWeight = 0, processedCount = 0;

            animationSteps.push({ type: 'init', concept: 'mst目标', lineStart: 8, lineEnd: 8, explanation: `已载入图“${graphData.name}”，准备执行 kruskal_label。`, currentEdgeId: null, mstEdges: [], rejectedEdges: [], stateSnapshot: labelState.snapshot(), totalWeight: 0, acceptedCount: 0, processedCount: 0, componentsCount: nodeIds.length, statsEntry: null });
            animationSteps.push({ type: 'sort-edges', concept: '边排序', lineStart: 10, lineEnd: 10, explanation: '先将所有边按权值从小到大排序，后续按这个顺序逐条考察。', currentEdgeId: null, mstEdges: [], rejectedEdges: [], stateSnapshot: labelState.snapshot(), totalWeight: 0, acceptedCount: 0, processedCount: 0, componentsCount: nodeIds.length, statsEntry: null });
            animationSteps.push({ type: 'init-components', concept: '标签维护', lineStart: 12, lineEnd: 14, explanation: '初始化标号数组：让每个点先拥有独立标号。', currentEdgeId: null, mstEdges: [], rejectedEdges: [], stateSnapshot: labelState.snapshot(), totalWeight: 0, acceptedCount: 0, processedCount: 0, componentsCount: nodeIds.length, statsEntry: null });

            for (const edge of graphData.sortedEdges) {
                processedCount++;
                const currentSnapshot = labelState.snapshot();
                const sameLabel = currentSnapshot.label[edge.u] === currentSnapshot.label[edge.v];

                const edgeIndex = graphData.sortedEdges.indexOf(edge) + 1;
                animationSteps.push({ type: 'consider-edge', concept: '边选择', lineStart: 18, lineEnd: 19, explanation: `当前考察第 ${edgeIndex} 条已排序边 ${edge.u}-${edge.v}，权值为 ${edge.w}。`, currentEdgeId: edge.id, mstEdges: clone(mstEdges), rejectedEdges: clone(rejectedEdges), stateSnapshot: currentSnapshot, totalWeight, acceptedCount: mstEdges.length, processedCount, componentsCount: getComponentsFromSnapshot(nodeIds, currentSnapshot).length, statsEntry: null });
                animationSteps.push({ type: 'detect-cycle', concept: sameLabel ? '环检测' : '标签维护', lineStart: 21, lineEnd: 21, explanation: sameLabel ? `label[${edge.u}] 与 label[${edge.v}] 相同，说明两个端点已在同一分量中，加入后会成环。` : `label[${edge.u}] 与 label[${edge.v}] 不同，说明加入该边不会形成环。`, currentEdgeId: edge.id, mstEdges: clone(mstEdges), rejectedEdges: clone(rejectedEdges), stateSnapshot: currentSnapshot, totalWeight, acceptedCount: mstEdges.length, processedCount, componentsCount: getComponentsFromSnapshot(nodeIds, currentSnapshot).length, statsEntry: null });

                if (sameLabel) {
                    rejectedEdges.push(edge.id);
                    const rejectSnapshot = labelState.snapshot();
                    const statsEntry = { edge: `${edge.u}-${edge.v}`, weight: edge.w, result: '拒绝', reason: '两端点标号相同，加入会成环', totalWeight };
                    statsRows.push(statsEntry);
                    animationSteps.push({ type: 'reject-edge', concept: '环检测', lineStart: 30, lineEnd: 30, explanation: `拒绝边 ${edge.u}-${edge.v}，因为两个端点标号相同。`, currentEdgeId: edge.id, mstEdges: clone(mstEdges), rejectedEdges: clone(rejectedEdges), stateSnapshot: rejectSnapshot, totalWeight, acceptedCount: mstEdges.length, processedCount, componentsCount: getComponentsFromSnapshot(nodeIds, rejectSnapshot).length, statsEntry });
                } else {
                    mstEdges.push(edge.id);
                    totalWeight += edge.w;
                    const relabelInfo = labelState.relabel(edge.u, edge.v);
                    const relabelSnapshot = labelState.snapshot();
                    const statsEntry = { edge: `${edge.u}-${edge.v}`, weight: edge.w, result: '接受', reason: `两端点标号不同，接受后把标号 ${relabelInfo.oldLabel} 整类改为 ${relabelInfo.newLabel}`, totalWeight };
                    statsRows.push(statsEntry);
                    animationSteps.push({ type: 'accept-edge', concept: '边选择', lineStart: 22, lineEnd: 22, explanation: `接受边 ${edge.u}-${edge.v}，把它加入最小生成树候选集合。`, currentEdgeId: edge.id, mstEdges: clone(mstEdges), rejectedEdges: clone(rejectedEdges), stateSnapshot: relabelSnapshot, totalWeight, acceptedCount: mstEdges.length, processedCount, componentsCount: getComponentsFromSnapshot(nodeIds, relabelSnapshot).length, statsEntry: null });
                    animationSteps.push({ type: 'union-components', concept: '标签维护', lineStart: 23, lineEnd: 27, explanation: `执行整体重标号：把所有标号为 ${relabelInfo.oldLabel} 的顶点统一改成 ${relabelInfo.newLabel}${relabelInfo.changedNodes.length ? `，本次变化顶点有 ${relabelInfo.changedNodes.join('、')}` : ''}。`, currentEdgeId: edge.id, mstEdges: clone(mstEdges), rejectedEdges: clone(rejectedEdges), stateSnapshot: relabelSnapshot, totalWeight, acceptedCount: mstEdges.length, processedCount, componentsCount: getComponentsFromSnapshot(nodeIds, relabelSnapshot).length, statsEntry });
                }
            }

            const finalSnapshot = labelState.snapshot();
            const finalComponents = getComponentsFromSnapshot(nodeIds, finalSnapshot).length;
            const success = mstEdges.length === nodeIds.length - 1;
            if (success) {
                animationSteps.push({ type: 'mst-complete', concept: 'mst目标', lineStart: 32, lineEnd: 33, explanation: `最终选中了 ${mstEdges.length} 条边，恰好等于 n-1 = ${nodeIds.length - 1}，因此这是一颗最小生成树。`, currentEdgeId: null, mstEdges: clone(mstEdges), rejectedEdges: clone(rejectedEdges), stateSnapshot: clone(finalSnapshot), totalWeight, acceptedCount: mstEdges.length, processedCount, componentsCount: finalComponents, statsEntry: null });
                animationSteps.push({ type: 'return-result', concept: 'mst目标', lineStart: 33, lineEnd: 34, explanation: `最终输出最小生成树边集，总权值为 ${totalWeight}。`, currentEdgeId: null, mstEdges: clone(mstEdges), rejectedEdges: clone(rejectedEdges), stateSnapshot: clone(finalSnapshot), totalWeight, acceptedCount: mstEdges.length, processedCount, componentsCount: finalComponents, statsEntry: null });
            } else {
                animationSteps.push({ type: 'disconnected-finish', concept: 'mst目标', lineStart: 32, lineEnd: 34, explanation: `最终只选中了 ${mstEdges.length} 条边，小于 n-1 = ${nodeIds.length - 1}，说明图不连通。`, currentEdgeId: null, mstEdges: clone(mstEdges), rejectedEdges: clone(rejectedEdges), stateSnapshot: clone(finalSnapshot), totalWeight, acceptedCount: mstEdges.length, processedCount, componentsCount: finalComponents, statsEntry: null });
                animationSteps.push({ type: 'return-result', concept: 'mst目标', lineStart: 34, lineEnd: 34, explanation: '最终只能得到最小生成森林，而不是完整最小生成树。', currentEdgeId: null, mstEdges: clone(mstEdges), rejectedEdges: clone(rejectedEdges), stateSnapshot: clone(finalSnapshot), totalWeight, acceptedCount: mstEdges.length, processedCount, componentsCount: finalComponents, statsEntry: null });
            }
        }

        function renderGraph(step) {
            const accepted = new Set(step.mstEdges || []), rejected = new Set(step.rejectedEdges || []), current = step.currentEdgeId;
            const nodeMap = {};
            graphData.nodes.forEach(node => { nodeMap[node.id] = node; });
            graphCanvas.innerHTML = '';

            graphData.edges.forEach(edge => {
                const from = nodeMap[edge.u], to = nodeMap[edge.v];
                const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
                line.setAttribute('x1', from.x); line.setAttribute('y1', from.y); line.setAttribute('x2', to.x); line.setAttribute('y2', to.y);
                line.setAttribute('stroke-width', accepted.has(edge.id) ? '5' : current === edge.id ? '4' : '3');
                line.setAttribute('stroke', accepted.has(edge.id) ? 'var(--accepted)' : rejected.has(edge.id) ? 'var(--rejected)' : current === edge.id ? 'var(--current)' : 'var(--edge-default)');
                if (rejected.has(edge.id)) line.setAttribute('stroke-dasharray', '8 6');
                graphCanvas.appendChild(line);

                const midX = (from.x + to.x) / 2, midY = (from.y + to.y) / 2;
                const labelBg = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
                labelBg.setAttribute('x', midX - 16); labelBg.setAttribute('y', midY - 14); labelBg.setAttribute('width', '32'); labelBg.setAttribute('height', '22'); labelBg.setAttribute('rx', '6'); labelBg.setAttribute('fill', 'white'); labelBg.setAttribute('stroke', '#cfd8dc');
                graphCanvas.appendChild(labelBg);

                const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                text.setAttribute('x', midX); text.setAttribute('y', midY + 1); text.setAttribute('text-anchor', 'middle'); text.setAttribute('font-size', '12'); text.setAttribute('fill', '#37474f'); text.textContent = edge.w;
                graphCanvas.appendChild(text);
            });

            graphData.nodes.forEach(node => {
                const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
                circle.setAttribute('cx', node.x); circle.setAttribute('cy', node.y); circle.setAttribute('r', '20'); circle.setAttribute('fill', 'var(--node-fill)'); circle.setAttribute('stroke', '#3949ab'); circle.setAttribute('stroke-width', '3');
                graphCanvas.appendChild(circle);

                const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                text.setAttribute('x', node.x); text.setAttribute('y', node.y + 5); text.setAttribute('text-anchor', 'middle'); text.setAttribute('font-size', '15'); text.setAttribute('font-weight', 'bold'); text.setAttribute('fill', '#1a237e'); text.textContent = node.id;
                graphCanvas.appendChild(text);
            });
        }

        function renderEdgeList(step) {
            edgeList.innerHTML = '';
            const accepted = new Set(step.mstEdges || []), rejected = new Set(step.rejectedEdges || []);
            graphData.sortedEdges.forEach(edge => {
                const li = document.createElement('li'); li.className = 'edge-item';
                let badge = '';
                if (step.currentEdgeId === edge.id) { li.classList.add('current'); badge = '<span class="edge-badge badge-current">当前</span>'; }
                if (accepted.has(edge.id)) { li.classList.add('accepted'); badge = '<span class="edge-badge badge-accepted">接受</span>'; }
                if (rejected.has(edge.id)) { li.classList.add('rejected'); badge = '<span class="edge-badge badge-rejected">拒绝</span>'; }
                li.innerHTML = `<span>${edge.u}-${edge.v} (w=${edge.w})</span>${badge}`;
                edgeList.appendChild(li);
            });
        }

        function renderComponents(step) {
            componentList.innerHTML = '';
            getComponentsFromSnapshot(graphData.nodes.map(n => n.id), step.stateSnapshot).forEach(group => {
                const chip = document.createElement('div'); chip.className = 'component-chip'; chip.textContent = `{ ${group.join(', ')} }`; componentList.appendChild(chip);
            });
        }

        function updateMetrics(step) {
            $('accepted-count-box').textContent = step.acceptedCount;
            $('total-weight-box').textContent = step.totalWeight;
            $('processed-count-box').textContent = step.processedCount;
            $('component-count-box').textContent = step.componentsCount;
            $('status').textContent = getStepStatus(step.type);
            $('current-op').textContent = step.explanation;
            const lineLabel = step.lineStart ? `${step.lineStart}` : (step.line || '-');
            $('current-line').textContent = lineLabel;
            $('current-edge').textContent = step.currentEdgeId ? formatEdgeById(step.currentEdgeId) : '-';
            $('current-weight').textContent = step.totalWeight;
            $('current-components').textContent = step.componentsCount;
        }

        function getStepStatus(type) {
            const map = { init: '准备就绪', 'sort-edges': '边排序中', 'consider-edge': '正在考察边', 'detect-cycle': '判断是否成环', 'accept-edge': '接受边', 'reject-edge': '拒绝边', 'union-components': '整体重标号', 'mst-complete': '最小生成树完成', 'disconnected-finish': '最小生成森林完成', 'return-result': '返回最终结果' };
            return map[type] || '执行中';
        }

        function formatEdgeById(edgeId) {
            const edge = graphData.edges.find(item => item.id === edgeId);
            return edge ? `${edge.u}-${edge.v} (w=${edge.w})` : '-';
        }

        function highlightCodeLine(lineNum) {
            codeLines.forEach(el => el.classList.remove('highlight', 'highlight-range-start', 'highlight-range-middle', 'highlight-range-end'));
            if (!lineNum) return;
            const target = Array.from(codeLines).find(el => Number(el.dataset.line) === Number(lineNum));
            if (!target) return;

            target.classList.add('highlight');

            const container = $('code-container');
            const targetTop = target.offsetTop;
            const targetBottom = target.offsetTop + target.offsetHeight;
            const visibleTop = container.scrollTop;
            const visibleBottom = visibleTop + container.clientHeight;

            if (targetTop < visibleTop) {
                container.scrollTop = Math.max(0, targetTop - 12);
            } else if (targetBottom > visibleBottom) {
                container.scrollTop = targetBottom - container.clientHeight + 12;
            }
        }

        function resetCodeHighlight() { codeLines.forEach(el => el.classList.remove('highlight', 'highlight-range-start', 'highlight-range-middle', 'highlight-range-end')); }

        function renderStats(rowsToShow) {
            statsBody.innerHTML = '';
            rowsToShow.forEach((row, idx) => {
                const tr = document.createElement('tr');
                tr.innerHTML = `<td>${idx + 1}</td><td>${row.edge}</td><td>${row.weight}</td><td>${row.result}</td><td>${row.reason}</td><td>${row.totalWeight}</td>`;
                statsBody.appendChild(tr);
            });
        }

        function getStepAt(index) {
            if (!animationSteps.length) return null;
            const safeIndex = Math.max(0, Math.min(index, animationSteps.length - 1));
            return animationSteps[safeIndex];
        }

        function getStatsRowsForStep(index) {
            if (!animationSteps.length) return [];
            const safeIndex = Math.max(0, Math.min(index, animationSteps.length - 1));
            const rows = [];
            for (let i = 0; i <= safeIndex; i++) {
                if (animationSteps[i]?.statsEntry) rows.push(animationSteps[i].statsEntry);
            }
            return rows;
        }

        function updateControlStates() {
            const hasSteps = animationSteps.length > 0;
            const atFirst = currentStep <= 0;
            const atLast = !hasSteps || currentStep >= animationSteps.length - 1;

            startBtn.disabled = !hasSteps || isStarted;
            prevBtn.disabled = !isStarted || isAutoRunning || atFirst;
            stepBtn.disabled = !isStarted || isAutoRunning || atLast;
            autoBtn.disabled = !isStarted || isAutoRunning || atLast;
            pauseBtn.disabled = !isAutoRunning;
            resetBtn.disabled = false;
        }

        function updateSummary(step) {
            const current = step || getStepAt(currentStep);
            if (!current) { summaryDisplay.textContent = ''; return; }
            const acceptedCount = current.acceptedCount || 0, totalWeight = current.totalWeight || 0, processed = current.processedCount || 0;
            const complete = current.type === 'mst-complete', disconnected = current.type === 'disconnected-finish';
            summaryDisplay.innerHTML = `当前已处理 <b>${processed}</b> 条边，接受 <b>${acceptedCount}</b> 条边，累计权值 <b>${totalWeight}</b>。` + (complete ? ' 当前结果是一棵完整的最小生成树。' : disconnected ? ' 当前结果是最小生成森林，因为原图不连通。' : ' 继续观察下一步的选择依据。');
        }

        function renderStepByIndex(index, options = {}) {
            const step = getStepAt(index);
            if (!step) return;
            currentStep = Math.max(0, Math.min(index, animationSteps.length - 1));
            renderGraph(step);
            renderEdgeList(step);
            renderComponents(step);
            updateMetrics(step);
            highlightCodeLine(step.lineStart || step.line);
            renderStats(getStatsRowsForStep(currentStep));
            updateSummary(step);
            showKnowledgeExplanation(step.concept || 'mst目标', step.explanation || '');
            if (options.countView && currentStep > furthestVisitedStep) {
                userProfile.viewedSteps += currentStep - furthestVisitedStep;
                furthestVisitedStep = currentStep;
            }
            if ((step.type === 'mst-complete' || step.type === 'disconnected-finish') && !runCompletionRecorded && options.recordCompletion !== false) {
                runCompletionRecorded = true;
                userProfile.completedRuns++;
                showCompletionMessage();
                $('status').textContent = step.type === 'disconnected-finish' ? '演示结束（最小生成森林）' : '演示结束（MST 完成）';
            }
            updateAnalysis();
            maybeRenderReport();
            updateControlStates();
        }

        function renderCurrentStepPreview() {
            renderStepByIndex(currentStep, { countView: false, recordCompletion: false });
        }

        function startSorting() {
            if (!graphData.nodes.length) { alert('请先加载图数据'); return; }
            isStarted = true;
            updateControlStates();
            $('status').textContent = '已开始';
            renderStepByIndex(currentStep, { countView: false, recordCompletion: false });
        }

        function stepForward() {
            if (!isStarted) { alert('请先点击“开始”'); return; }
            if (currentStep >= animationSteps.length - 1) { showCompletionMessage(); return; }
            renderStepByIndex(currentStep + 1, { countView: true });
        }

        function stepBackward() {
            if (!isStarted) { alert('请先点击“开始”'); return; }
            if (isAutoRunning) pauseAutoRun();
            if (currentStep <= 0) return;
            renderStepByIndex(currentStep - 1, { countView: false, recordCompletion: false });
        }

        function finishRun(step) {
            pauseAutoRun();
            updateControlStates();
            $('status').textContent = step.type === 'disconnected-finish' ? '演示结束（最小生成森林）' : '演示结束（MST 完成）';
        }

        function startAutoRun() {
            if (!isStarted || isAutoRunning || currentStep >= animationSteps.length - 1) return;
            isAutoRunning = true;
            updateControlStates();
            animationInterval = setInterval(() => {
                if (currentStep >= animationSteps.length - 1) {
                    pauseAutoRun();
                    return;
                }
                stepForward();
                const step = getStepAt(currentStep);
                if (step && (step.type === 'mst-complete' || step.type === 'disconnected-finish' || currentStep >= animationSteps.length - 1)) {
                    finishRun(step);
                }
            }, Number(speedSlider.value));
        }

        function pauseAutoRun() {
            if (!isAutoRunning) return;
            clearInterval(animationInterval);
            isAutoRunning = false;
            updateControlStates();
        }

        function resetViewState(fromSetup = false) {
            pauseAutoRun(); currentStep = 0; furthestVisitedStep = 0; runCompletionRecorded = false; isStarted = false;
            $('status').textContent = fromSetup ? '准备就绪' : '已重置';
            $('current-op').textContent = graphData.name ? `已载入图“${graphData.name}”，等待开始。` : '-';
            $('current-line').textContent = '-'; $('current-edge').textContent = '-'; $('current-weight').textContent = '0'; $('current-components').textContent = graphData.nodes.length ? graphData.nodes.length : '0';
            renderStats([]); resetCodeHighlight();
            updateControlStates();
        }

        function updateSpeed() {
            speedValue.textContent = speedSlider.value + 'ms';
            if (isAutoRunning) { pauseAutoRun(); startAutoRun(); }
        }

        function showCompletionMessage() {
            completionMessage.style.display = 'block';
            setTimeout(() => completionMessage.style.display = 'none', 2800);
        }

        function appendChatMsg(role, text) {
            const msg = document.createElement('div');
            msg.className = 'chat-msg ' + role;
            msg.innerHTML = text.replace(/\n/g, '<br>');
            chatMessages.appendChild(msg);
            chatMessages.scrollTop = chatMessages.scrollHeight;
        }

        function localChat(question) {
            const q = question.toLowerCase();
            let best = null, bestScore = 0;
            qaKnowledgeBase.forEach(item => {
                let score = 0;
                item.keywords.forEach(kw => { if (q.includes(kw.toLowerCase())) score++; });
                if (score > bestScore) { bestScore = score; best = item; }
            });
            if (best && bestScore > 0) return { answer: best.answer, topic: best.topic };
            return { answer: '我暂时没有匹配到最合适的预设答案。你可以试试这些问题：什么是最小生成树、为什么先排序边、标号法如何判断成环、为什么要整体重标号、Kruskal 和 Prim 有什么区别。', topic: '' };
        }

        function sendChatMessage(prefilledText) {
            const text = (prefilledText || chatInput.value).trim();
            if (!text) return;
            appendChatMsg('user', text);
            chatHistory.push({ role: 'user', text });
            chatInput.value = '';
            chatSendBtn.disabled = true;
            userProfile.askedQuestions++;

            const typingEl = document.createElement('div');
            typingEl.className = 'typing-indicator';
            typingEl.textContent = '本地知识库匹配中...';
            chatMessages.appendChild(typingEl);
            chatMessages.scrollTop = chatMessages.scrollHeight;

            setTimeout(() => {
                const response = localChat(text);
                typingEl.remove();
                appendChatMsg('ai', response.answer);
                chatHistory.push({ role: 'ai', text: response.answer });
                if (response.topic) {
                    userProfile.questionTopics.push(response.topic);
                    const topicAskCount = userProfile.questionTopics.filter(topic => topic === response.topic).length;
                    if (topicAskCount >= 2) {
                        userProfile.markedConcepts[response.topic]++;
                    }
                    userProfile.conceptScores[response.topic] = clamp(userProfile.conceptScores[response.topic] - (topicAskCount >= 2 ? 6 : 3), 0, 100);
                    showKnowledgeExplanation(response.topic, response.answer);
                }
                chatSendBtn.disabled = false;
                updateAnalysis(); maybeRenderReport();
            }, 280);
        }

        function markConceptWeak(concept, note) {
            userProfile.markedConcepts[concept]++;
            userProfile.conceptScores[concept] = clamp(userProfile.conceptScores[concept] - 12, 0, 100);
            if (note) {
                const prefix = notesTextarea.value && !notesTextarea.value.endsWith('\n') ? '\n' : '';
                notesTextarea.value += `${prefix}[知识点疑问] ${conceptLabels[concept]}：${note}\n`;
            }
            updateAnalysis(); maybeRenderReport();
        }

        function initConceptButtons() {
            document.querySelectorAll('.ask-chip').forEach(btn => btn.addEventListener('click', () => sendChatMessage(btn.dataset.question)));
            knowledgeAskBtn.addEventListener('click', () => sendChatMessage(conceptQuestions[currentKnowledgeConcept] || '什么是最小生成树'));
            knowledgeMarkBtn.addEventListener('click', () => {
                const reason = prompt(`你对“${conceptLabels[currentKnowledgeConcept]}”哪里不理解？可简单描述：`, '');
                if (reason === null) return;
                markConceptWeak(currentKnowledgeConcept, reason || '用户点击了“我对这里不理解”');
                showKnowledgeExplanation(currentKnowledgeConcept, `已将该知识点记录为薄弱点。${reason || ''}`);
            });
        }

        function initCodeMarking() {
            codeLines.forEach(lineEl => {
                const concept = lineEl.dataset.knowledge;
                lineEl.addEventListener('click', () => showKnowledgeExplanation(concept, `你当前查看的是第 ${lineEl.dataset.line} 行 C++ 代码。`));
                const markBtn = lineEl.querySelector('.mark-icon');
                markBtn.addEventListener('click', e => {
                    e.stopPropagation();
                    const lineNum = Number(lineEl.dataset.line);
                    const reason = prompt(`请描述你对第 ${lineNum} 行（${conceptLabels[concept]}）的疑问：`, userMarks[lineNum]?.note || '');
                    if (reason === null) return;
                    userMarks[lineNum] = { line: lineNum, concept, note: reason, timestamp: new Date().toLocaleString() };
                    lineEl.classList.add('user-marked');
                    if (!userProfile.markedCodeLines.includes(lineNum)) userProfile.markedCodeLines.push(lineNum);
                    markConceptWeak(concept, reason || `第${lineNum}行被标记为不理解`);
                    showKnowledgeExplanation(concept, `你对第 ${lineNum} 行提出了疑问：${reason || '未填写具体内容'}`);
                });
            });
        }

        function calculateSkillScores() {
            const scores = userProfile.conceptScores;
            const viewedBonus = Math.min(4, Math.round((userProfile.viewedSteps / Math.max(animationSteps.length, 1)) * 4));
            const runBonus = Math.min(4, userProfile.completedRuns * 2);
            Object.keys(scores).forEach(concept => {
                const wrongCount = userProfile.quizHistory.filter(item => item.concept === concept && !item.correct).length;
                const rightCount = userProfile.quizHistory.filter(item => item.concept === concept && item.correct).length;
                const extraWrongCount = userProfile.quizHistory.filter(item => item.concept === concept && !item.correct && (item.source === 'extra' || item.source === 'followup')).length;
                const extraRightCount = userProfile.quizHistory.filter(item => item.concept === concept && item.correct && (item.source === 'extra' || item.source === 'followup')).length;
                let value = 50 + viewedBonus + runBonus;
                value -= userProfile.markedConcepts[concept] * 10;
                value -= wrongCount * 14;
                value += rightCount * 10;
                value -= extraWrongCount * 6;
                value += extraRightCount * 4;
                scores[concept] = clamp(value, 0, 100);
            });
        }

        function renderSkillBars() {
            const colors = { mst目标: '#43a047', 边排序: '#1e88e5', 环检测: '#fb8c00', 标签维护: '#8e24aa', 边选择: '#5e35b1', 复杂度: '#e53935' };
            const container = $('skill-bars');
            container.innerHTML = '';
            Object.entries(userProfile.conceptScores).forEach(([concept, score]) => {
                const row = document.createElement('div');
                row.className = 'skill-bar';
                row.innerHTML = `<span class="skill-name">${conceptLabels[concept]}</span><div class="bar-track"><div class="bar-fill" style="width:${score}%;background:${colors[concept]};"></div></div><span class="skill-val">${score}%</span>`;
                container.appendChild(row);
            });
        }

        function getWeakConcepts() {
            const entries = Object.entries(userProfile.conceptScores);
            const explicitMarked = Object.entries(userProfile.markedConcepts).filter(([, count]) => count > 0).map(([concept]) => concept);
            const wrongQuizConcepts = [...new Set(userProfile.quizHistory.filter(item => !item.correct).map(item => item.concept))];
            return entries
                .filter(([concept, score]) => score < 60 || explicitMarked.includes(concept) || wrongQuizConcepts.includes(concept))
                .sort((a, b) => {
                    const aWrong = userProfile.quizHistory.filter(item => item.concept === a[0] && !item.correct).length;
                    const bWrong = userProfile.quizHistory.filter(item => item.concept === b[0] && !item.correct).length;
                    const aMarked = userProfile.markedConcepts[a[0]];
                    const bMarked = userProfile.markedConcepts[b[0]];
                    return (bWrong + bMarked) - (aWrong + aMarked) || a[1] - b[1];
                })
                .map(([concept]) => concept);
        }

        function getConfusedConcepts() {
            const topicHits = { mst目标: 0, 边排序: 0, 环检测: 0, 标签维护: 0, 边选择: 0, 复杂度: 0 };
            userProfile.questionTopics.forEach(topic => { if (topicHits[topic] !== undefined) topicHits[topic]++; });
            return Object.keys(topicHits).filter(concept => topicHits[concept] >= 2 || userProfile.markedConcepts[concept] > 0);
        }

        function shuffleArray(items) {
            const arr = [...items];
            for (let i = arr.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [arr[i], arr[j]] = [arr[j], arr[i]];
            }
            return arr;
        }

        function renderWeakList() {
            const weak = getWeakConcepts(); const list = $('weak-list'); list.innerHTML = '';
            if (!weak.length) { list.innerHTML = '<li>当前没有明显薄弱项，可以继续通过提问或答题深入理解。</li>'; return; }
            weak.slice(0, 4).forEach(concept => {
                const item = document.createElement('li');
                const wrongCount = userProfile.quizHistory.filter(x => x.concept === concept && !x.correct).length;
                item.textContent = `${conceptLabels[concept]}：掌握度 ${userProfile.conceptScores[concept]}%，疑问标记 ${userProfile.markedConcepts[concept]} 次，错题 ${wrongCount} 次。`;
                list.appendChild(item);
            });
        }

        function renderRecommendations() {
            const weak = getWeakConcepts(); const list = $('recommendation-list'); list.innerHTML = '';
            if (!weak.length) { list.innerHTML = '<li>建议尝试生成针对性题目，验证你是否真的掌握了每个部分。</li>'; return; }
            weak.slice(0, 3).forEach(concept => {
                const li = document.createElement('li'); li.textContent = `${conceptLabels[concept]}：${conceptAdvice[concept]}`; list.appendChild(li);
            });
        }

        function updateAnalysis() { calculateSkillScores(); renderSkillBars(); renderWeakList(); renderRecommendations(); }

        function buildQuizQueue() {
            const confusedConcepts = getConfusedConcepts();
            const usedIds = new Set();
            const baseQueue = [];
            const extraQueue = [];
            const allBaseCandidates = shuffleArray(Object.entries(quizBank).flatMap(([concept, items]) =>
                items.filter(item => !item.id.includes('follow-')).map(item => ({ ...item, concept }))
            ));

            confusedConcepts.forEach(concept => {
                const preferred = allBaseCandidates.find(item => item.concept === concept && !usedIds.has(item.id) && !askedQuizIds.has(item.id));
                if (preferred && baseQueue.length < QUIZ_BASE_COUNT) {
                    baseQueue.push({ ...preferred, source: 'base', isTargeted: true });
                    usedIds.add(preferred.id);
                }
            });

            allBaseCandidates.forEach(item => {
                if (baseQueue.length >= QUIZ_BASE_COUNT) return;
                if (usedIds.has(item.id)) return;
                baseQueue.push({ ...item, source: 'base', isTargeted: confusedConcepts.includes(item.concept) });
                usedIds.add(item.id);
            });

            confusedConcepts.forEach(concept => {
                const extras = shuffleArray((quizBank[concept] || []).filter(item => !item.id.includes('follow-') && !usedIds.has(item.id)));
                extras.forEach(item => {
                    extraQueue.push({ ...item, concept, source: 'extra', isTargeted: true });
                    usedIds.add(item.id);
                });
            });

            return {
                baseQueue,
                extraQueue,
                queue: [...baseQueue, ...extraQueue],
                planMeta: {
                    confusedConcepts,
                    baseCount: baseQueue.length,
                    extraCount: extraQueue.length
                }
            };
        }

        function chooseQuizConcept() {
            const weak = getWeakConcepts();
            if (weak.length) return weak[0];
            return Object.keys(quizBank).sort((a, b) => userProfile.conceptScores[a] - userProfile.conceptScores[b])[0];
        }

        function generateQuiz() {
            if (!quizSession.started || quizSession.finished) {
                const plan = buildQuizQueue();
                quizSession = {
                    started: true,
                    queue: plan.queue,
                    baseQueue: plan.baseQueue,
                    extraQueue: plan.extraQueue,
                    answeredCount: 0,
                    finished: false,
                    planMeta: plan.planMeta
                };
                if (!quizSession.queue.length) {
                    quizContent.innerHTML = '<div class="quiz-question">当前没有可用题目。</div>';
                    $('next-quiz-btn').disabled = true;
                    return;
                }
            }
            const nextQuiz = quizSession.queue[quizSession.answeredCount];
            if (!nextQuiz) {
                finishQuizSession();
                return;
            }
            currentQuiz = { ...nextQuiz, concept: nextQuiz.concept || chooseQuizConcept() };
            askedQuizIds.add(currentQuiz.id);
            renderQuiz(currentQuiz);
            $('next-quiz-btn').disabled = true;
        }

        function finishQuizSession() {
            quizSession.finished = true;
            currentQuiz = null;
            $('next-quiz-btn').disabled = true;
            quizContent.innerHTML = '<div class="quiz-question">本轮题目已完成，已生成最终学习报告。</div>';
            maybeRenderReport();
        }

        function renderQuiz(quiz) {
            quizContent.innerHTML = '';
            const title = document.createElement('div');
            title.className = 'quiz-question';
            title.innerHTML = `<b>知识点：</b>${conceptLabels[quiz.concept]}<br><b>题目：</b>${quiz.stem}`;
            quizContent.appendChild(title);
            const optionsWrap = document.createElement('div'); optionsWrap.className = 'quiz-options';
            quiz.options.forEach((option, idx) => {
                const btn = document.createElement('button');
                btn.className = 'quiz-option'; btn.textContent = `${String.fromCharCode(65 + idx)}. ${option}`;
                btn.addEventListener('click', () => submitQuizAnswer(idx));
                optionsWrap.appendChild(btn);
            });
            quizContent.appendChild(optionsWrap);
        }

        function submitQuizAnswer(choice) {
            if (!currentQuiz) return;
            const correct = choice === currentQuiz.correctIndex;
            const explanationBlock = document.createElement('div');
            explanationBlock.className = 'quiz-feedback ' + (correct ? 'feedback-correct' : 'feedback-wrong');
            explanationBlock.innerHTML = `<div><b>${correct ? '回答正确' : '回答错误'}</b></div><div>正确答案：${String.fromCharCode(65 + currentQuiz.correctIndex)}. ${currentQuiz.options[currentQuiz.correctIndex]}</div><div style="margin-top:6px;"><b>你选择的选项说明：</b>${currentQuiz.explanations[choice]}</div><div style="margin-top:6px;"><b>为什么正确答案要选：</b>${currentQuiz.explanations[currentQuiz.correctIndex]}</div><div style="margin-top:6px;"><b>其他选项为什么不能选：</b></div><ul class="answer-list">${currentQuiz.options.map((opt, idx) => { if (idx === choice || idx === currentQuiz.correctIndex) return ''; return `<li>${String.fromCharCode(65 + idx)}：${currentQuiz.explanations[idx]}</li>`; }).join('')}</ul>`;
            quizContent.appendChild(explanationBlock);
            quizContent.querySelectorAll('.quiz-option').forEach(btn => btn.disabled = true);
            userProfile.quizHistory.push({ concept: currentQuiz.concept, questionId: currentQuiz.id, correct, chosen: choice, source: currentQuiz.source || 'base', isTargeted: !!currentQuiz.isTargeted, timestamp: new Date().toLocaleString() });
            if (!correct) {
                userProfile.misconceptionFlags[currentQuiz.concept].push(currentQuiz.misconceptionTag);
                userProfile.conceptScores[currentQuiz.concept] = clamp(userProfile.conceptScores[currentQuiz.concept] - 14, 0, 100);
                if (currentQuiz.followupOnWrong) {
                    const followup = Object.values(quizBank).flat().find(item => item.id === currentQuiz.followupOnWrong);
                    if (followup && !quizSession.queue.some(item => item.id === followup.id)) {
                        quizSession.queue.push({ ...followup, concept: currentQuiz.concept, source: 'followup', isTargeted: true });
                    }
                }
            } else {
                userProfile.conceptScores[currentQuiz.concept] = clamp(userProfile.conceptScores[currentQuiz.concept] + 10, 0, 100);
            }
            quizSession.answeredCount++;
            $('next-quiz-btn').disabled = false;
            if (quizSession.answeredCount >= quizSession.queue.length) {
                $('next-quiz-btn').textContent = '查看最终报告';
            } else {
                $('next-quiz-btn').textContent = '下一题';
            }
            updateAnalysis();
            maybeRenderReport();
        }

        function maybeRenderReport() {
            if (quizSession.finished) {
                reportSection.style.display = 'block';
                generateReport(true);
            } else {
                reportSection.style.display = 'none';
            }
        }

        function generateReport(showFinal = false) {
            reportContent.innerHTML = '';
            if (!showFinal) {
                const placeholderCard = document.createElement('div');
                placeholderCard.className = 'report-card';
                const totalPlanned = quizSession.started ? quizSession.queue.length : 0;
                const answered = quizSession.started ? quizSession.answeredCount : 0;
                placeholderCard.innerHTML = `<h4>学习总结</h4><div class="summary-text">完成本轮答题后生成最终学习报告。当前答题进度：${answered} / ${totalPlanned || '未开始'}。</div>`;
                reportContent.appendChild(placeholderCard);
                return;
            }
            const weak = getWeakConcepts().slice(0, 3);
            const baseAnswered = userProfile.quizHistory.filter(item => item.source === 'base');
            const extraAnswered = userProfile.quizHistory.filter(item => item.source === 'extra' || item.source === 'followup');
            const baseCorrect = baseAnswered.filter(item => item.correct).length;
            const extraCorrect = extraAnswered.filter(item => item.correct).length;

            const summaryCard = document.createElement('div');
            summaryCard.className = 'report-card';
            summaryCard.innerHTML = `<h4>学习总结</h4><div class="summary-text">本轮固定基础题共 ${quizSession.planMeta.baseCount || baseAnswered.length} 道，答对 ${baseCorrect} 道；针对性补题与强化题共 ${extraAnswered.length} 道，答对 ${extraCorrect} 道。最终结论以答题表现为主，浏览步骤 ${userProfile.viewedSteps} 次、完成演示 ${userProfile.completedRuns} 次仅作为辅助参考。</div>`;
            reportContent.appendChild(summaryCard);

            const evidenceCard = document.createElement('div');
            evidenceCard.className = 'report-card';
            evidenceCard.innerHTML = '<h5>学习判定依据</h5>';
            const evidenceList = document.createElement('ul');
            const confused = quizSession.planMeta.confusedConcepts || [];
            evidenceList.innerHTML = `<li>基础题正确率：${baseAnswered.length ? `${baseCorrect}/${baseAnswered.length}` : '暂无'}</li><li>追加题正确率：${extraAnswered.length ? `${extraCorrect}/${extraAnswered.length}` : '暂无追加题'}</li><li>主动暴露疑问的知识点：${confused.length ? confused.map(concept => conceptLabels[concept]).join('、') : '无'}</li>`;
            evidenceCard.appendChild(evidenceList);
            reportContent.appendChild(evidenceCard);

            const weaknessCard = document.createElement('div'); weaknessCard.className = 'report-card'; weaknessCard.innerHTML = '<h5>当前不足之处</h5>';
            const weaknessList = document.createElement('ul');
            if (!weak.length) weaknessList.innerHTML = '<li>当前没有明显的薄弱项，建议继续通过编程练习巩固。</li>';
            else {
                weak.forEach(concept => {
                    const wrongCount = userProfile.quizHistory.filter(x => x.concept === concept && !x.correct).length;
                    const targetedWrong = userProfile.quizHistory.filter(x => x.concept === concept && !x.correct && (x.source === 'extra' || x.source === 'followup')).length;
                    const evidence = [];
                    if (wrongCount > 0) evidence.push(`相关错题 ${wrongCount} 次`);
                    if (targetedWrong > 0) evidence.push(`针对性补题仍错 ${targetedWrong} 次`);
                    if (userProfile.markedConcepts[concept] > 0) evidence.push(`标记不理解 ${userProfile.markedConcepts[concept]} 次`);
                    if (!evidence.length) evidence.push(`当前掌握度仅 ${userProfile.conceptScores[concept]}%`);
                    const li = document.createElement('li');
                    li.innerHTML = `<b>${conceptLabels[concept]}</b>：${evidence.join('，')}。建议：${conceptAdvice[concept]}`;
                    weaknessList.appendChild(li);
                });
            }
            weaknessCard.appendChild(weaknessList); reportContent.appendChild(weaknessCard);

            const exerciseCard = document.createElement('div'); exerciseCard.className = 'report-card'; exerciseCard.innerHTML = '<h5>针对性编程练习</h5>';
            const exerciseList = document.createElement('ul'); const targets = weak.length ? weak : Object.keys(conceptExercises).slice(0, 2);
            targets.forEach(concept => (conceptExercises[concept] || []).slice(0, 2).forEach(ex => {
                const li = document.createElement('li'); li.textContent = `${conceptLabels[concept]}：${ex}`; exerciseList.appendChild(li);
            }));
            exerciseCard.appendChild(exerciseList); reportContent.appendChild(exerciseCard);

            const externalCard = document.createElement('div'); externalCard.className = 'report-card'; externalCard.innerHTML = '<h5>可延伸的外部练习方向</h5>';
            const externalList = document.createElement('ul');
            targets.forEach(concept => (externalPractice[concept] || []).slice(0, 2).forEach(item => {
                const li = document.createElement('li'); li.textContent = `${conceptLabels[concept]}：${item}`; externalList.appendChild(li);
            }));
            externalCard.appendChild(externalList); reportContent.appendChild(externalCard);
        }

        function toggleManualInput() {
            const box = $('manual-input-container');
            box.style.display = box.style.display === 'none' ? 'block' : 'none';
        }

        function parseManualInput() {
            const nodeText = $('manual-nodes').value.trim(), edgeText = $('manual-edges').value.trim();
            if (!nodeText || !edgeText) { alert('请先输入节点与边集'); return; }
            const nodes = nodeText.split(',').map(x => x.trim()).filter(Boolean);
            if (nodes.length < 3) { alert('节点数至少为 3'); return; }
            const nodeSet = new Set(nodes);
            if (nodeSet.size !== nodes.length) { alert('节点名称存在重复，请确保每个节点只出现一次'); return; }
            const lines = edgeText.split(/\n+/).map(x => x.trim()).filter(Boolean), edges = [];
            for (const line of lines) {
                const parts = line.split(',').map(x => x.trim());
                if (parts.length !== 3) { alert('边格式错误，请使用 u,v,w'); return; }
                const [u, v, wText] = parts, w = Number(wText);
                if (!nodeSet.has(u) || !nodeSet.has(v)) { alert(`边 ${line} 中出现未定义节点`); return; }
                if (u === v) { alert(`边 ${line} 是自环，当前不允许自环`); return; }
                if (Number.isNaN(w)) { alert(`边 ${line} 的权值不是有效数字`); return; }
                edges.push([u, v, w]);
            }
            loadGraph({ name: '手动输入图', nodes, edges });
            $('manual-input-container').style.display = 'none';
        }

        function generateRandomConnectedGraph() {
            const count = Number($('node-count').value);
            if (Number.isNaN(count) || count < 3 || count > 8) { alert('节点个数请控制在 3 到 8 之间'); return; }
            const nodes = Array.from({ length: count }, (_, i) => String.fromCharCode(65 + i));
            const edges = [];
            for (let i = 1; i < count; i++) {
                const parent = Math.floor(Math.random() * i);
                edges.push([nodes[parent], nodes[i], Math.floor(Math.random() * 9) + 1]);
            }
            for (let i = 0; i < count; i++) {
                for (let j = i + 1; j < count; j++) {
                    if (Math.random() < 0.28 && !edges.some(edge => (edge[0] === nodes[i] && edge[1] === nodes[j]) || (edge[0] === nodes[j] && edge[1] === nodes[i]))) {
                        edges.push([nodes[i], nodes[j], Math.floor(Math.random() * 9) + 1]);
                    }
                }
            }
            loadGraph({ name: '随机连通图', nodes, edges });
        }

        function saveNotes() {
            const text = notesTextarea.value;
            if (!text) { alert('笔记内容为空'); return; }
            const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
            const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'kruskal_learning_notes.txt'; a.click(); URL.revokeObjectURL(a.href);
        }

        function loadNotes() {
            const input = document.createElement('input'); input.type = 'file'; input.accept = 'text/plain';
            input.onchange = e => {
                const file = e.target.files[0]; if (!file) return;
                const reader = new FileReader(); reader.onload = ev => notesTextarea.value = ev.target.result; reader.readAsText(file);
            };
            input.click();
        }

        function clearNotes() { if (confirm('确定要清空笔记吗？')) notesTextarea.value = ''; }

        function bindEvents() {
            $('load-preset-btn').addEventListener('click', () => loadGraph(PRESET_GRAPHS[$('preset-select').value]));
            $('random-btn').addEventListener('click', generateRandomConnectedGraph);
            $('manual-btn').addEventListener('click', toggleManualInput);
            $('submit-btn').addEventListener('click', parseManualInput);
            startBtn.addEventListener('click', startSorting);
            prevBtn.addEventListener('click', stepBackward);
            stepBtn.addEventListener('click', stepForward);
            autoBtn.addEventListener('click', startAutoRun);
            pauseBtn.addEventListener('click', pauseAutoRun);
            resetBtn.addEventListener('click', () => { resetViewState(false); renderCurrentStepPreview(); });
            speedSlider.addEventListener('input', updateSpeed);
            chatSendBtn.addEventListener('click', () => sendChatMessage());
            chatInput.addEventListener('keydown', e => { if (e.key === 'Enter') sendChatMessage(); });
            $('generate-quiz-btn').addEventListener('click', generateQuiz);
            $('next-quiz-btn').addEventListener('click', generateQuiz);
            $('save-btn').addEventListener('click', saveNotes);
            $('load-btn').addEventListener('click', loadNotes);
            $('clear-btn').addEventListener('click', clearNotes);
        }

        function init() {
            bindEvents();
            initConceptButtons();
            initCodeMarking();
            updateSpeed();
            loadGraph(PRESET_GRAPHS.basic);
            updateAnalysis();
            maybeRenderReport();
            showKnowledgeExplanation('mst目标');
        }

        init();
    
  cleanup = () => {
    if (animationInterval) clearInterval(animationInterval);
  };
});

onUnmounted(() => {
  cleanup?.();
});
</script>

<template>
  <div class="k-agent-root">
<div class="container">
        <h1 class="main-title">Kruskal算法智能体</h1>
      

        <div class="row">
            <div class="col input-panel">
                <div class="panel-title">图数据输入模块</div>
                <div class="input-section">
                    <div class="input-group">
                        <label for="preset-select">预设图:</label>
                        <select id="preset-select">
                            <option value="basic">基础连通图</option>
                            <option value="equal">存在相同权值</option>
                            <option value="disconnected">非连通图</option>
                        </select>
                    </div>
                    <div class="input-group">
                        <label for="node-count">节点个数:</label>
                        <input type="number" id="node-count" min="3" max="8" value="6">
                    </div>
                    <div class="btn-group">
                        <button id="load-preset-btn" class="btn btn-primary">加载预设图</button>
                        <button id="random-btn" class="btn btn-random">随机生成连通图</button>
                        <button id="manual-btn" class="btn btn-manual">手动输入图</button>
                    </div>
                    <div id="manual-input-container" style="display:none;">
                        <div class="manual-row">
                            <label for="manual-nodes">节点:</label>
                            <input id="manual-nodes" type="text" placeholder="例如: A,B,C,D,E">
                        </div>
                        <div class="manual-row">
                            <label for="manual-edges">边集:</label>
                            <textarea id="manual-edges" placeholder="每行一条边，格式: A,B,4&#10;A,C,2&#10;B,D,5"></textarea>
                        </div>
                        <button id="submit-btn" class="btn btn-submit">提交图数据</button>
                    </div>
                </div>
            </div>
            <div class="col concept-panel">
                <div class="panel-title">Kruskal 算法思想</div>
                <div class="concept-content">
                    <p>Kruskal 算法用于求无向带权图的最小生成树。它遵循<strong>贪心策略</strong>：每次优先选择当前权值最小、且不会形成环的边。</p>
                    <ol>
                        <li><b>边排序：</b>先将所有边按权值从小到大排序。</li>
                        <li><b>依次考察：</b>从最小边开始逐条检查。</li>
                        <li><b>判断成环：</b>若当前边两个端点的标号相同，则加入后会形成环，应拒绝。</li>
                        <li><b>整体重标号：</b>若标号不同，就把这条边加入生成树，并把旧标号对应的整类顶点改成新标号。</li>
                        <li><b>终止条件：</b>当已选边数达到 n-1 时，最小生成树构建完成。</li>
                    </ol>
                    <p style="margin-top:8px;">Kruskal 的核心复杂度仍来自边排序，常写作 <b>O(E log E)</b>；而标号法每次合并可能还要扫描全部顶点更新标号，因此实现更直观，但单次合并开销也更明显。</p>
                </div>
            </div>
        </div>

        <div class="row-single">
            <div class="col prereq-panel">
                <div class="panel-title">前置知识准备</div>
                <div class="prereq-grid">
                    <div class="prereq-card">
                        <span class="prereq-tag">生成树</span>
                        <h4>最小生成树在解决什么问题</h4>
                        <p>目标是在保证所有节点连通、整体无环的前提下，让边权总和尽量小。如果图不连通，结果就会变成最小生成森林。</p>
                    </div>
                    <div class="prereq-card">
                        <span class="prereq-tag">贪心</span>
                        <h4>为什么要先排序边</h4>
                        <p>Kruskal 每一步都优先尝试当前最便宜的边，因此会先把所有边按权值升序排列，再依次判断是否可以加入。</p>
                    </div>
                    <div class="prereq-card">
                        <span class="prereq-tag">判环</span>
                        <h4>什么叫“加入后成环”</h4>
                        <p>如果一条边的两个端点本来就已经连通，那么再加这条边一定会形成环。生成树不能有环，所以这种边必须拒绝。</p>
                    </div>
                    <div class="prereq-card">
                        <span class="prereq-tag">标号法</span>
                        <h4>标号法需要会什么</h4>
                        <ul>
                            <li><b>label[i]</b>：表示顶点 i 当前所属连通分量的标号</li>
                            <li><b>label[u] == label[v]</b>：说明两个点已经在同一分量中</li>
                            <li>作用：接受边后，把旧标号对应的整类顶点统一改成新标号</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>

